function model(p) {
  // A health plan's core data model (ten objects, their relations and owning teams) and three processes that walk it:
  // enrolment, a claim, and an appeal. Each event creates, links or updates one object; the picture follows the path.
  // Names, fields, owners and the processes are illustrative, not a product's schema.
  const process = Math.max(0, Math.min(2, Math.round(p.process)));
  const ownership = Math.round(p.ownership) === 1;
  const sf = Math.round(p.names) === 1;
  const TEAMS = [
    { id: 'membership', label: 'Membership' }, { id: 'network', label: 'Provider network' }, { id: 'claims', label: 'Claims operations' },
    { id: 'service', label: 'Member services' }, { id: 'finance', label: 'Finance' }
  ];
  // [id, generic label, Salesforce-flavoured label, owning team, key fields]
  const O = [
    ['member', 'Member', 'Account (Person)', 'membership', ['member number', 'date of birth', 'address']],
    ['policy', 'Policy', 'Member Plan', 'membership', ['plan', 'effective date', 'group']],
    ['provider', 'Provider', 'Healthcare Provider', 'network', ['NPI', 'specialty', 'network status']],
    ['auth', 'Prior authorization', 'Care Request', 'claims', ['service', 'decision', 'valid until']],
    ['claim', 'Claim', 'Claim', 'claims', ['claim number', 'service date', 'status']],
    ['line', 'Claim line', 'Claim Line Item', 'claims', ['procedure code', 'billed', 'allowed']],
    ['payment', 'Payment', 'Payment', 'finance', ['amount', 'payee', 'run date']],
    ['case', 'Case', 'Case', 'service', ['reason', 'channel', 'owner']],
    ['appeal', 'Appeal', 'Care Request (appeal)', 'service', ['grounds', 'reviewer', 'outcome']],
    ['letter', 'Letter', 'Communication', 'service', ['template', 'sent on', 'channel']]
  ];
  const objects = O.map(([id, g, s, team, fields], k) => ({ id, label: sf ? s : g, generic: g, team, teamLabel: TEAMS.find(t => t.id === team).label, fields, k }));
  const R = [
    ['member', 'policy', 'is covered by', '1 : n'], ['member', 'claim', 'has', '1 : n'], ['provider', 'claim', 'submits', '1 : n'], ['policy', 'claim', 'pays under', '1 : n'],
    ['claim', 'line', 'contains', '1 : n'], ['member', 'auth', 'requests', '1 : n'], ['provider', 'auth', 'asks for', '1 : n'], ['claim', 'payment', 'settled by', '1 : 1'],
    ['provider', 'payment', 'paid to', '1 : n'], ['member', 'case', 'raises', '1 : n'], ['claim', 'appeal', 'disputed by', '1 : n'], ['case', 'appeal', 'tracks', '1 : 1'],
    ['member', 'letter', 'receives', '1 : n'], ['claim', 'letter', 'explained by', '1 : n'],
    ['member', 'provider', 'chooses as PCP', 'n : 1'], ['auth', 'claim', 'covers', '1 : n'], ['appeal', 'auth', 're-opens', '1 : 1']
  ];
  const relations = R.map(([from, to, label, card], i) => ({ i, from, to, label, card }));
  const P = [
    { id: 'enrolment', title: 'Enrolment', events: [
      ['member', 'create', 'A new member record is created from the enrolment file.'],
      ['policy', 'create', 'The plan and effective date become a policy linked to the member.', 'member'],
      ['provider', 'link', 'A primary care provider from the network is assigned.', 'member'],
      ['letter', 'create', 'The welcome letter and ID card are generated for the member.', 'member'] ] },
    { id: 'claim', title: 'A claim', events: [
      ['provider', 'update', 'A provider sees the member; the visit becomes a claim they submit.'],
      ['claim', 'create', 'The claim is created against the member, the provider and the policy.', 'member'],
      ['line', 'create', 'Each procedure on the visit is a claim line with its codes and billed amount.', 'claim'],
      ['auth', 'update', 'Adjudication checks whether the service needed, and had, a prior authorization.', 'claim'],
      ['policy', 'update', 'Benefits and the provider contract set the allowed amounts; the claim is approved.', 'claim'],
      ['payment', 'create', 'The payment run pays the provider for the claim.', 'claim'],
      ['letter', 'create', 'An explanation of benefits goes to the member.', 'claim'] ] },
    { id: 'appeal', title: 'An appeal', events: [
      ['claim', 'update', 'A claim is denied: no prior authorization on file for the service.'],
      ['letter', 'create', 'The denial letter reaches the member with the reason code.', 'claim'],
      ['case', 'create', 'The member calls; member services opens a case.', 'member'],
      ['appeal', 'create', 'An appeal is filed against the claim and tracked by the case.', 'claim'],
      ['auth', 'update', 'Clinical review finds the service was medically necessary; the authorization is granted after the fact.', 'appeal'],
      ['claim', 'update', 'The claim is re-adjudicated and approved.', 'appeal'],
      ['payment', 'create', 'The next payment run pays the provider.', 'claim'],
      ['letter', 'create', 'A corrected explanation of benefits goes to the member; the case is closed.', 'claim'] ] }
  ];
  const proc = P[process], STEP = 3;
  const events = proc.events.map(([object, action, note, via], i) => ({ i, object, action, note, via: via || null, start: i * STEP, dur: STEP }));
  const path = [...new Set(events.map(e => e.object))];
  const touched = objects.filter(o => path.includes(o.id)).map(o => o.id);
  const teamsInvolved = [...new Set(touched.map(id => objects.find(o => o.id === id).team))];
  let handoffs = 0; for (let i = 1; i < events.length; i++) { const a = objects.find(o => o.id === events[i - 1].object).team, b = objects.find(o => o.id === events[i].object).team; if (a !== b) handoffs++; }
  // Relations the process travels: each event's link to the object it came from
  const travelled = events.filter(e => e.via).map(e => { const r = relations.find(x => (x.from === e.via && x.to === e.object) || (x.from === e.object && x.to === e.via)); return r ? r.i : null; }).filter(i => i !== null);
  const duration = events.length * STEP + 2;
  const steps = events.map(e => ({ id: 'e' + e.i, t: e.start, title: (e.action === 'create' ? 'Create ' : e.action === 'link' ? 'Link ' : 'Update ') + objects.find(o => o.id === e.object).label, note: e.note }));
  const summary = proc.title + ' touches ' + touched.length + ' of ' + objects.length + ' objects across ' + teamsInvolved.length + ' teams with ' + handoffs + ' hand-off' + (handoffs === 1 ? '' : 's') + (ownership ? '; the owners decide who must agree before the model changes.' : '.');
  return { process: proc.id, processTitle: proc.title, ownership, sf, teams: TEAMS, objects, relations, events, path, touched, travelled, teamsInvolved, handoffs, steps, duration, markers: steps.map(s => s.t), summary };
}

checkCode:
function check(p) {
  const m = model(p), ids = new Set(m.objects.map(o => o.id));
  // Every event, relation and path entry points at a real object, and the touched set is exactly the objects the events visit
  const eventsOk = m.events.every(e => ids.has(e.object) && (!e.via || ids.has(e.via)));
  const relOk = m.relations.every(r => ids.has(r.from) && ids.has(r.to) && r.from !== r.to);
  const visited = new Set(m.events.map(e => e.object));
  const touchedOk = m.touched.length === visited.size && m.touched.every(id => visited.has(id)) && m.path.every(id => visited.has(id));
  // Every 'via' link is an existing relation, so the picture never draws an edge the model does not have
  const viaOk = m.events.filter(e => e.via).every(e => m.relations.some(r => (r.from === e.via && r.to === e.object) || (r.from === e.object && r.to === e.via)));
  // Teams involved and hand-offs follow from the owners of the touched objects
  const teamOf = id => m.objects.find(o => o.id === id).team;
  const teams = new Set(m.touched.map(teamOf));
  let h = 0; for (let i = 1; i < m.events.length; i++) if (teamOf(m.events[i - 1].object) !== teamOf(m.events[i].object)) h++;
  const teamsOk = teams.size === m.teamsInvolved.length && h === m.handoffs;
  // Events run back to back and the markers match them; the names switch changes labels only
  const timeOk = m.events.every((e, i) => e.start === i * 3) && m.markers.length === m.events.length && m.duration > m.events[m.events.length - 1].start;
  const other = model(Object.assign({}, p, { names: Math.round(p.names) === 1 ? 0 : 1 }));
  const namesOk = JSON.stringify(other.path) === JSON.stringify(m.path) && other.handoffs === m.handoffs && other.relations.length === m.relations.length;
  const pass = eventsOk && relOk && touchedOk && viaOk && teamsOk && timeOk && namesOk;
  return {
    pass,
    detail: m.processTitle + ': ' + m.events.length + ' events over ' + m.touched.length + ' objects' + (touchedOk ? '' : ' (touched set wrong)') + ', ' + m.teamsInvolved.length + ' teams, ' + m.handoffs + ' hand-offs' + (teamsOk ? '' : ' (recount differs)') +
      '; every link travelled is a relation of the model' + (viaOk ? '' : ' (violated)') + '; the names switch changes labels only' + (namesOk ? '.' : ' (it changed the structure).')
  };
}
